import{_ as n,a0 as r,w as i,s as u,I as t,x as s,a1 as p,A as l,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"你需要知道的 DevSecOps 流程及工具 | LCTT x X-CMD","titleTemplate":false,"description":"你需要知道的 DevSecOps 流程及工具 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"你需要知道的 DevSecOps 流程及工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"你需要知道的 DevSecOps 流程及工具 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20191010 DevSecOps pipelines and tools- What you need to know","title":"你需要知道的 DevSecOps 流程及工具","tag":"201910","desc":""},"relativePath":"201910/20191010 DevSecOps pipelines and tools- What you need to know.md","filePath":"[post].md"}'),a={name:"201910/20191010 DevSecOps pipelines and tools- What you need to know.md"};function v(D,e,S,f,O,m){const o=r("Link");return i(),u("div",null,[e[25]||(e[25]=t("h1",{id:"你需要知道的-devsecops-流程及工具",tabindex:"-1"},[s("你需要知道的 DevSecOps 流程及工具 "),t("a",{class:"header-anchor",href:"#你需要知道的-devsecops-流程及工具","aria-label":"Permalink to “你需要知道的 DevSecOps 流程及工具”"},"​")],-1)),e[26]||(e[26]=t("blockquote",null,[t("p",null,"DevSecOps 對 DevOps 進行了改進，以確保安全性仍然是該過程的一個重要部分。")],-1)),e[27]||(e[27]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/201910/23/002010fvzh282e8ghhdzpk.jpg",alt:""})],-1)),e[28]||(e[28]=t("p",null,"到目前為止，DevOps 在 IT 世界中已廣為人知，但其並非完美無缺。試想一下，你在一個項目的現代應用程序交付中實施了所有 DevOps 工程實踐。你已經到達開發流程的末尾，但是滲透測試團隊（內部或外部）檢測到安全漏洞並提出了報告。現在，你必須重新啓動所有流程，並要求開發人員修復該漏洞。",-1)),e[29]||(e[29]=t("p",null,"在基於 DevOps 的軟件開發生命週期（SDLC）系統中，這並不繁瑣，但它確實會浪費時間並影響交付進度。如果從 SDLC 初期就已經集成了安全性，那麼你可能已經跟蹤到了該故障，並在開發流程中就消除了它。但是，如上述情形那樣，將安全性推到開發流程的最後將導致更長的開發生命週期。",-1)),e[30]||(e[30]=t("p",null,"這就是引入 DevSecOps 的原因，它以自動化的方式鞏固了整個軟件交付週期。",-1)),t("p",null,[e[3]||(e[3]=s("在現代 DevOps 方法中，組織廣泛使用容器託管應用程序，我們看到 ",-1)),p(o,{href:"https://opensource.com/resources/what-is-kubernetes"},{default:l(()=>[...e[0]||(e[0]=[s("Kubernetes",-1)])]),_:1}),e[4]||(e[4]=s(" 和 ",-1)),p(o,{href:"https://opensource.com/article/18/9/what-istio"},{default:l(()=>[...e[1]||(e[1]=[s("Istio",-1)])]),_:1}),e[5]||(e[5]=s(" 使用的較多。但是，這些工具都有其自身的漏洞。例如，雲原生計算基金會（CNCF）最近完成了一項 ",-1)),p(o,{href:"https://www.cncf.io/blog/2019/08/06/open-sourcing-the-kubernetes-security-audit/"},{default:l(()=>[...e[2]||(e[2]=[s("kubernetes 安全審計",-1)])]),_:1}),e[6]||(e[6]=s("，發現了幾個問題。DevOps 開發流程中使用的所有工具在流程運行時都需要進行安全檢查，DevSecOps 會推動管理員去監視工具的存儲庫以獲取升級和補丁。",-1))]),e[31]||(e[31]=t("h3",{id:"什麼是-devsecops",tabindex:"-1"},[s("什麼是 DevSecOps? "),t("a",{class:"header-anchor",href:"#什麼是-devsecops","aria-label":"Permalink to “什麼是 DevSecOps?”"},"​")],-1)),e[32]||(e[32]=t("p",null,"與 DevOps 一樣，DevSecOps 是開發人員和 IT 運營團隊在開發和部署軟件應用程序時所遵循的一種思維方式或文化。它將主動和自動化的安全審計以及滲透測試集成到敏捷應用程序開發中。",-1)),t("p",null,[e[8]||(e[8]=s("要使用 ",-1)),p(o,{href:"https://resources.whitesourcesoftware.com/blog-whitesource/devsecops"},{default:l(()=>[...e[7]||(e[7]=[s("DevSecOps",-1)])]),_:1}),e[9]||(e[9]=s("，你需要：",-1))]),e[33]||(e[33]=d('<ul><li>從 SDLC 開始就引入安全性概念，以最大程度地減少軟件代碼中的漏洞。</li><li>確保每個人（包括開發人員和 IT 運營團隊）共同承擔在其任務中遵循安全實踐的責任。</li><li>在 DevOps 工作流程開始時集成安全控件、工具和流程。這些將在軟件交付的每個階段啓用自動安全檢查。</li></ul><p>DevOps 一直致力於在開發和發佈過程中包括安全性以及質量保證（QA）、資料庫管理和其他所有方面。然而，DevSecOps 是該過程的一個演進，以確保安全永遠不會被遺忘，成為該過程的一個重要部分。</p><h3 id="瞭解-devsecops-流程" tabindex="-1">瞭解 DevSecOps 流程 <a class="header-anchor" href="#瞭解-devsecops-流程" aria-label="Permalink to “瞭解 DevSecOps 流程”">​</a></h3><p>典型的 DevOps 流程有不同的階段；典型的 SDLC 流程包括計劃、編碼、構建、測試、發佈和部署等階段。在 DevSecOps 中，每個階段都會應用特定的安全檢查。</p><ul><li><strong>計劃</strong>：執行安全性分析並創建測試計劃，以確定在何處、如何以及何時進行測試的方案。</li><li><strong>編碼</strong>：部署整理工具和 Git 控件以保護密碼和 API 密鑰。</li><li><strong>構建</strong>：在構建執行代碼時，請結合使用靜態應用程序安全測試（SAST）工具來跟蹤代碼中的缺陷，然後再部署到生產環境中。這些工具針對特定的編程語言。</li><li><strong>測試</strong>：在運行時使用動態應用程序安全測試（DAST）工具來測試您的應用程序。 這些工具可以檢測與用户身份驗證，授權，SQL 注入以及與 API 相關的端點相關的錯誤。</li><li><strong>發佈</strong>：在發佈應用程序之前，請使用安全分析工具來進行全面的滲透測試和漏洞掃描。</li><li><strong>部署</strong>：在運行時完成上述測試後，將安全的版本發送到生產中以進行最終部署。</li></ul><h3 id="devsecops-工具" tabindex="-1">DevSecOps 工具 <a class="header-anchor" href="#devsecops-工具" aria-label="Permalink to “DevSecOps 工具”">​</a></h3><p>SDLC 的每個階段都有可用的工具。有些是商業產品，但大多數是開源的。在我的下一篇文章中，我將更多地討論在流程的不同階段使用的工具。</p><p>隨着基於現代 IT 基礎設施的企業安全威脅的複雜性增加，DevSecOps 將發揮更加關鍵的作用。然而，DevSecOps 流程將需要隨着時間的推移而改進，而不是僅僅依靠同時實施所有安全更改即可。這將消除回溯或應用交付失敗的可能性。</p><hr>',9)),t("p",null,[e[11]||(e[11]=s("via: ",-1)),p(o,{href:"https://opensource.com/article/19/10/devsecops-pipeline-and-tools"},{default:l(()=>[...e[10]||(e[10]=[s("https://opensource.com/article/19/10/devsecops-pipeline-and-tools",-1)])]),_:1})]),t("p",null,[e[16]||(e[16]=s("作者：",-1)),p(o,{href:"https://opensource.com/users/sagarnangare"},{default:l(()=>[...e[12]||(e[12]=[s("Sagar Nangare",-1)])]),_:1}),e[17]||(e[17]=s(" 選題：",-1)),p(o,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[13]||(e[13]=[s("lujun9972",-1)])]),_:1}),e[18]||(e[18]=s(" 譯者：",-1)),p(o,{href:"https://github.com/lnrCoder"},{default:l(()=>[...e[14]||(e[14]=[s("lnrCoder",-1)])]),_:1}),e[19]||(e[19]=s(" 校對：",-1)),p(o,{href:"https://github.com/wxy"},{default:l(()=>[...e[15]||(e[15]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[22]||(e[22]=s("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[20]||(e[20]=[s("LCTT",-1)])]),_:1}),e[23]||(e[23]=s(" 原創編譯，",-1)),p(o,{href:"https://linux.cn/"},{default:l(()=>[...e[21]||(e[21]=[s("Linux中國",-1)])]),_:1}),e[24]||(e[24]=s(" 榮譽推出",-1))])])}const b=n(a,[["render",v]]);export{C as __pageData,b as default};
